/**
 * Raw per-user, per-period engagement signals. In the real system these
 * would be aggregated from event logs (logins, searches, schedule edits);
 * here they're just given to you directly, already rolled up per period.
 */
export type EngagementSignals = {
  userId: string;
  /** A period identifier, e.g. "2026-01" for a monthly rollup. Opaque string. */
  period: string;
  logins: number;
  searches: number;
  scheduleEdits: number;
};

/** The set of scoring formulas this system currently knows about. */
export type FormulaName = "weightedV1" | "weightedV2";

/**
 * One computed activity score for a single (user, period), tagged with the
 * formula that produced it.
 */
export type ActivityScoreRecord = {
  userId: string;
  period: string;
  formulaVersion: FormulaName;
  score: number;
  /** ISO timestamp of when this record was computed (for audit purposes). */
  computedAt: string;
};
